from collections import Counter, deque

def components(grid, region_rows, bg):
    seen=set(); comps=[]
    for r in region_rows:
        for c in range(24):
            if grid[r][c]==bg or (r,c) in seen: continue
            color=grid[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                a,b=q.pop(); cells.append((a,b))
                for da,db in [(1,0),(-1,0),(0,1),(0,-1)]:
                    x,y=a+da,b+db
                    if x in region_rows and 0<=y<24 and (x,y) not in seen and grid[x][y]==color:
                        seen.add((x,y)); q.append((x,y))
            comps.append((color,cells))
    return comps

def solve_generic(g):
    # canvases rows whose endpoints same non-bg and interior uniform
    canvas=[]; covered=set()
    for r in range(30):
        if g[r][0]==g[r][-1] and g[r][0]!=g[0][0] and len(set(g[r][1:-1]))==1:
            if r not in covered:
                rr=r
                while rr<30 and g[rr][0]==g[r][0] and g[rr][-1]==g[r][-1] and len(set(g[rr][1:-1]))==1:
                    covered.add(rr); rr+=1
                canvas.append((list(range(r,rr)),g[r][0],g[r][1]))
    firstcanvas=min(rs[0] for rs,_,_ in canvas)
    bg=g[0][0]
    comps=components(g,set(range(firstcanvas)),bg)
    out=[row[:] for row in g]
    for r in range(firstcanvas):
        for c in range(24): out[r][c]=bg
    for color,cells in comps:
        for rs,bord,fill in canvas:
            if fill==color:
                maxr=max(r for r,c in cells); dr=rs[-1]-maxr
                for r,c in cells: out[r+dr][c]=bord
    return out
